window.K3_QRAW = window.K3_QRAW || [];
window.K3_QRAW.push.apply(window.K3_QRAW, [{"id": "edu-principle|ep-06|b63|42", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 42, "q": "课程实施的过程并不是预定课程计划径直实现的过程，而是课程计划与班级或学校实践情境在课程目标、内容、方法、组织模式等方面相互调整、改变的过程。这种观点属于课程取向中的（）", "opts": ["相互适应取向", "创生取向", "忠实取向", "批判取向"], "a": 0, "exp": "本题的解题关键在于“相互调整、改变”，创生取向强调创造，忠实取向强调遵守。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|43", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 43, "q": "主张用集体审议的方式解决课程问题，同时把教师和学生视为课程的主体和创造者的）课程模式是（", "opts": ["目标模式", "过程模式", "实践模式", "文化模式"], "a": 2, "exp": "实践模式强调课程的实践价值和动态过程，追求课程的实践性，重视课程开发中结果与过程、目的与手段的统一，主张用集体审议的方式解决课程问题，同时把教师和学生视为课程的主体和创造者。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|44", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 44, "q": "通过确定人类生活的十大活动领域，再分析儿童完成这些活动需要的能力，进而确定）课程目标的教育家是（", "opts": ["泰勒", "斯宾塞", "布卢姆", "博比特"], "a": 3, "exp": "1918年，博比特出版了（课程），这是教育史上第一本课程论专著。博比特主张用科学的方法确定教育目标。博比特对成人生活活动做了大规模调查，将社会生活活动分为10大类：语言活动、健康活动、公民活动、一般社交活动、休闲娱乐活动、维持个人心理健康的活动、宗教活动、家庭活动、非职业性的实际活动、个人的职业活动。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|45", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 45, "q": "在课程内容组织中，强调保持各种课程内容之间的横向关系，以便学生获得一种统一的观念，并把行为与所学课程内容统一起来，这体现了课程逻辑规则的（）", "opts": ["连续性", "顺序性", "整合性", "发展性"], "a": 2, "exp": "题干所述体现了课程逻辑规则的整合性。在课程内容组织中，强调保持课程内容之间的横向关系，帮助学生获得统一的观念并将行为与所学课程内容统一起来，体现了课程内容的整合性。这种整合性有助于学生更好地理解和应用所学知识，形成统一的认知框架。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|46", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 46, "q": "泰勒课程设计的四个步骤包括确定教育目标、选择学习经验，组织学习经验和（）", "opts": ["研究学生", "评价学习结果", "安排课程内容", "诊断学习需要"], "a": 1, "exp": "本题考查的知识点是泰勒原理。泰勒在《课程与教学的基本原理》中，提出了关于课程编制的四个问题，即泰勒原理：①确定教育目标；②根据目标选择学习经验；③根据目标组织学习经验；④评价学习结果。因此，B选项正确。A、C、D三项均不属于泰勒原理的内容。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|47", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 47, "q": "刘老师上课时，一位同学突然提出了一个很有意思的问题，引起了全班同学的探索兴趣，刘老师后半节课就围绕这个问题而展开了教学。此后半节课的教学目标属于", "opts": ["行为性目标", "生成性目标", "表现性目标", "普遍性目标"], "a": 1, "exp": "本题考查的知识点是课程目标价值取向。美国课程理论专家舒伯特认为，课程目标的形式取向主要有四种类型：普遍性目标、行为性目标、生成性目标和表现性目标。A选项，行为性目标是以设计课程行为结果的方式对课程进行规范和指导的目标，它指明了完成课程后学生自身应发生的行为变化，目标具体，可操作性强。B选项，生成性目标又称“形成性目标”，是在教育情境中随教育过程的展开而自然生成的课程目标。它注重过程，强调目标的生成应该视课堂教学的实际情况来定。C选项，表现性目标指学生在教育情境中产生的个性化表现，它强调学生的个性发展。表现性目标关注的是学生在活动中表现出来的某种程度上首创反应的形式，而不是事先规定的结果。它只是为学生提供活动的领域，至于结果则是开放的。D选项，普追性目标是根据一定的哲学和伦理、意识形态、社会政治的需要，对课程进行规范与指导的总括性和原则性的目标，它对各门学科都有普遍的指导意义。题干中的刘老师后半节课就围绕学生突然提出的一个很有意思的问题展开教学，是在教育情境中随教育过程的展开而自然生成的课程目标，属于生成性目标。故本题选B选项。课程改革", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b67|48", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 48, "q": "新版《义务教育课程方案》中指出，劳动课程要避免停留在表层的、泛化的活动设计，要注重活动过程中的思想教育，强调通过活动引导学生感悟劳动价值，进而培育劳动精神，这体现了劳动教育（", "opts": ["鲜明的思想性", "突出的社会性", "显著的实践性", "独特的科学性"], "a": 0, "exp": "题干所述体现了劳动教育的鲜明的思想性。新版《义务教育课程方案）动引导学生感悟劳动的价值，培养劳动精神。这种做法强调了劳动教育的思想性，旨在通过劳动活动激发学生的思考和认知，培养他们的价值观和精神品质。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b67|49", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 49, "q": "2022年新版《义务教育课程方案和课程标准》中将劳动课程独立为新的科目，进一步）强调了劳动课程的地位和价值。以下哪项不属于劳动课程的特点（", "opts": ["鲜明的思想性", "突出的社会性", "显著的实践性", "严密的理论性"], "a": 3, "exp": "不属于劳动课程的特点的是严密的理论性。劳动课程通常强调实践性、思想性和社会性，旨在培养学生的实践能力、思想品质和社会责任感。.虽然理论性在某的主要特点。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b67|50", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 50, "q": "以下哪一项不属于我国新课程改革带来的教学观的变革（", "opts": ["从关注学科转向关注人", "从重理论学习转向重实践操作", "从教会学生知识转向教会学生学习", "从以教育者为中心转向以学习者为中心"], "a": 1, "exp": "本题考查的知识点是新课改背景下的教学观。新课改的教学观强调：彰口：亡转向“关注人”。B选项从重理论学习转向重实践操作与教学观的内容不符。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b67|51", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 51, "q": "根据新课程改革的理念，教师应该是学生学习活动的（①合作者②控制者③支配者④管理者", "opts": ["①②", "②③", "③④", "①④"], "a": 3, "exp": "本题考查的知识点是新课改背景下的教师观。新课改背景下的教师观强调教师是学生学习的促进者；新课改教学行为的转变强调教师在教学上的帮助和引导。“②控制者”和“③支配者”过于强调教师的支配地位，不符合新课改下的教师观，错误。因此，排除A、B、C选项。故本题选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b67|52", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 52, "q": "某市教育局下达了“在全市小学开展国学经典诵读系列活动的实施意见”，该举措在于培养学生核心素养中的（）", "opts": ["健康生活", "实践创新", "人文底蕴", "学会学习"], "a": 2, "exp": "本题考查的知识点是中国学生发展核心紫养。中国学生发展核心紫养以培养“全面发展的人”为核心，分为文化基础、自主发展、社会参与三个方面，综合表现为人文底蕴、科学精神、学会学习、健康生活、责任担当、实践创新六大素养。A选项，健康生活主要是学生在认识自我、发展身心、规划人生等方面的综合表现。具体包括珍爱生命、健全人格、自我管理等基本要点。B选项，实践创新主要是学生在日常活动、问题解决、适应挑战等方面所形成的实践能力、创新意识和行为表现。具体包括劳动意识、问题解决、技术应用等基本要点。C选项，人文底蕴主要是学生在学习、理解、运用人文领域知识和技能等方面所形成的基本能力、情感态度和价值取向。具体包括人文积淀、人文情怀和审美情趣等基本要点。D选项，学会学习主要是学生在学习意识形成、学习方式方法选择、学习进程评估调控等方面的综合表现。具体包括乐学善学、勤于反思、信息意识等基本要点。“在全市小学开展国学经典诵读系列活动的实施意见？目的是让学生学习人文领域的知识，形成正确的情感态度和价值取向。故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b67|53", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 53, "q": "21世纪初，我国开展了新一轮基础教育课程改革。关于此次改革的具体目标，下列表述不正确的是（）", "opts": ["改变学科本位的课程结构", "改变过于注重知识传授的倾向", "改变过于强调接受学习的现状", "改变课程管理过于松散的状况"], "a": 3, "exp": "本题考查的是新课改的具体目标。我国新课程改革的具体目标包括：（1）实现课程功能的转变；2）体现课程结构的均衡性、综合性和选择性；3）密切课程内容与生活、与实际的联系；（4）改善学生的学习方式；(5）建立与素质教育理念相一致的评价与考试制度；（6）建立三级课程管理体系。A选项，改变学科本位的课程结构是指改变课程结构过于强调学科本位、科目过多和缺乏整合的现状，整体设置九年一贯课程门类和课时比例，并设置综合课程，以适应不同地区和学生发展的需求，体现课程结构的均衡性、综合性和选择性。B选项，改变过于注重知识传授的倾向是指强调形成积极主动的学习态度，引导学生学会学习、学会生存、学会做人。新课程的教学目标为三维目标，即知识与技能、过程与方法、情感态度价值观，新课程背景下的课堂教学就是要把原来目标单一（知识与技能）的课堂转变为目标多维的课堂。C选项，改变过于强调接受学习的现状是指改变课程实施过于强调接受学习、死记硬背、机械训练的现状，倡导自主学习、探究学习、合作学习的学习方式。D选项，改变课程管理过于松散的状况，与目前课程管理的现状恰好相反，当前课程管理的主要问题是过于集中而非松散。对此，新课改的目标是改变课程管理过于集中的状况，实行国家、地方、学校三级课程管理，增强课程对地方、学校及学生的适应性。D选项表述不正确，故本题选D选项。5$一·第六章课程", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b70|1", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 1, "q": "【2014年311真题7】20世纪60年代初美国课程改革代表人物布鲁纳的《教育过程）一书面世。下列对该书基本主张的概括中，不正确的是（", "opts": ["强调学术标准，注重教学内容的现代化", "强调学科基本结构的学习和发现教学法的运用【研大］", "强调中小学教师和课程专家在课程改革中的作用", "主张任何学科都能以某种方式教给任何年龄阶段的任何儿童"], "a": 0, "exp": "A选项强调学术标准，注重教学内容的现代化不正确。《教育过程》一书主张注重对学生的学习过程和学习方法的培养，而非只是强调教育内容的现代化。书中提出了探究性学习、问题解决和个性化学习等教育理念，秉持以学生为中心的教育思想。同时，该书也支持多样化的教育内容和学习方法的运用，而非完全注重学术标准。B选项强调学科基本结构的学习和发现教学法的运用是正确的。布鲁纳在《教育过程》中提倡“学科形态”的观念，即教育应该根据学科的现有形态组织课程，将学科的基本结构和概念系统的学习作为课程中心，同时也强调向学生呈现知识体系的合理性和系统性。他认为学生更应该学习现有学科的方法和技能，而不仅仅是知识和技术。C选项强调中小学教师和课程专家在课程改革中的作用是正确的。布鲁纳主张教师和教育专家参与到教育课程改革的过程中来，他们能够帮助提高教育的有效性，提高教育质量和学生学习成果。布鲁纳强调了课程改革是一个发展性的过程，需要有广泛的参与者贡献自己的经验和知识。D选项主张任何学科都能以某种方式教给任何年龄阶段的任何儿童是正确的。布鲁纳认为学习某种学科应该以“主题模块”的形式进行，这意味着任何学科都应该由一系列方便理解和学习的主题构成，并且应该把课程导向问题解决和知识体系理解方面，而非单纯强调知识点的死记硬背。此外，他主张将不同科目的知识在学习和教学中相互融合，这也暗示了任何学科都能以某种方式教给任何年龄阶段的任何儿童。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b70|2", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 2, "q": "【2014年311真题8】倾向于废除直接教学、废除考试的教学理论流派是（", "opts": ["行为主义教学理论", "认知主义教学理论", "人本主义教学理论", "建构主义教学理论"], "a": 2, "exp": "人本主义教学理论主张废除直接教学，重视学生自学；主张废除考试,重视自我评价。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b70|3", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 3, "q": "【2016年311真题8】布鲁纳认知主义教学理论提出的教学原则有（", "opts": ["动机原则、结构原则、程序原则、强化原则", "高速度原则、高难度原则、理论知识起主导作用原则", "直观性原则、量力性原则、巩固性原则、彻底性原则", "及时反馈原则、“小步子”原则、自定步调原则、积极反应原则"], "a": 0, "exp": "本题属于对识记性知识的考查。布鲁纳认知主义教学理论提出的教学原则有动机原则、结构原则、程序原则和强化原则。B选项赞科夫提出的教学原则为高难度原则、高速度原则、理论知识起主导作用原则、使学生理解学习过程原则和使全体学生包括最差的学生都得到一般发展的原则。C选项夸美纽斯提出的主要教学原则有直观性原则、激发学生求知欲望原则、巩固性原则、量力性原则、系统性原则和循序渐进性原则。D选项斯金纳提出的教学原则有及时反馈原则、小步子原则、自定步调原则和积极反应原则。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b70|4", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 4, "q": "【2023年311真题8】主张教学活动应致力于提高学生的自我意识、引导学生进行人格化和个性化学习的教学论流派是（）", "opts": ["行为主义", "认知主义", "人本主义", "社会互动论"], "a": 2, "exp": "A选项，行为主义认为教学的本质在于如何进行强化；B选项，认知主义认为教学是促进学习者内部认知结构的形成或改组：D选项，社会互动论强调社会互动在教学中的重要作用。C选项，人本主义主张教学活动应致力于提高学生的自我意识、引导学生进行人格化和个性化学习，促进学生成为一个完整的人。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b73|5", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 5, "q": "提出教学过程以解决学生的情感问题为目标的教学理论是（）", "opts": ["皮亚杰的认知结构发展理论", "维果茨基的“文化-历史”理论", "罗杰斯的非指导性教学理论", "赫尔巴特的传统教学理论"], "a": 2, "exp": "本题考查的知识点是罗杰斯的非指导性教学理论。C选项，非指导性教学理论中的非指导性教学法又叫促进教学法，是美国著名心理学家卡尔·罗杰斯首倡的。所谓非指导性教学法，就是创造一种有利于学生学习的气氛，教师（促进者）充分地信任学生、了解学生、尊重学生，从而使学生在整个学习过程中都感到安全与自信，充分显露自己的潜能；朝向自我实现。罗杰斯强调学生的情感、个性、直觉等非认知要素的发展，主张教学过程是认知与非认知、理性与非理性的统一，教学不仅仅局限于学生“颈部以上”，而应致力于完整的人的培养。因此，C选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b75|6", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 6, "q": "【2007年311真题10】教学的内容、方法、分量和进度要适合学生的身心发展，是他们能够接受的，但又要有一定的难度，需要经过努力才能掌握，以促进学生的身心发展。）这条原则是（", "opts": ["因材施教原则", "启发性原则", "巩固性原则", "量力性原则"], "a": 3, "exp": "量力性原则，又称可接受性原则或发展性原则，是指教学的内容、方法和进度要适合学生已有的发展水平，既是学生能够接受的；又要有一定的难度，激励他们经过努力才能掌握，以便有效地促进学生的身心发展。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b75|7", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 7, "q": "【2016年311真题9】学生出现下列哪种情形，教师可以考虑采用惩罚来教育（", "opts": ["认知错误", "明知故犯", "作业错误", "情绪失控"], "a": 1, "exp": "当学生明知故犯时可以使用适度惩罚的方法。针对认知错误和作业错误，教师需要加强教育引导。学生情绪失控需要教师帮助学生进行心理疏导和情绪调节。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b75|8", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 8, "q": "【2021年311真题1】某化学老师在讲授元素周期表时，还与学生分享了门捷列夫发现化学元素周期律的故事，鼓励学生勇于探索真理、发现化学的奥秘。该老师遵循的）教学原则是（", "opts": ["理论联系实际原则", "启发性原则", "思想性与科学性统一的原则", "直观性原则"], "a": 2, "exp": "“讲授元素周期表”属于“科学性”，“鼓励学生勇于探索真理”属于“思一·第七章教学想性”，该老师遵循的是思想性与科学性相统一的原则。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b75|9", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 9, "q": "述的同伴冲突事件编写同伴调解剧的脚本；学生轮流扮演事件中的当事人和旁观者，反复演练调解过程，不断完善脚本；最后，各组登台演出，相互评议，形成了一个最佳调解方案。这堂课使用的教学方法有（）", "opts": ["角色扮演法、实践锻炼法、情境模拟法", "角色扮演法、讨论法、情境模拟法", "实践锻炼法、讨论法、角色扮演法", "实践锻炼法、讨论法、情境模拟法"], "a": 1, "exp": "B选项角色扮演法、讨论法、情境模拟法是正确的。首先，这个活动使用了角色扮演法，老师让学生在模拟同伴冲突的情境中，扮演不同的角色，更深人地理解问题，并且在演练中逐渐发掘和掌握解决冲突的方案。其次，这个活动使用了讨论法，各组学生登台演出，相互评议，在讨论中形成最佳调解方案。最后，这个活动使用了情境模拟法。通过模拟同伴冲突的情境，学生们得以更深人地了解问题的细节和背景，更好地理解他人需求，进而提高他们在类似情境下解决问题的能力。实践锻炼法指的是采用实践操作的方法，让学生在实践中探索、体验、反思并总结经验。虽然这个活动有一部分是通过模拟情境实践操作，并且在活动中进行经验总结，但是这个活动并不需要学生参与到实际冲突的处理中去，并非采用具体的实践方式。因此实践锻炼法并不是这个活动的明显特点。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b75|10", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 10, "q": "【2023年311真题13】孟懿子问孝。子日：“无违。”孟武伯问孝。子日：“父母唯其疾之忧。”子夏问孝。子日：“色难。有事，弟子服其劳；有酒食，先生饿，曾是以为孝乎？”（节选自（论语》）上述孔子与其弟子对话蕴含的教学原则是（", "opts": ["学思结合", "因材施教", "启发诱导", "循序渐进"], "a": 1, "exp": "译文：孟懿子问孔子何为孝？孔子说：“不违背即是孝”。孟武伯问孔子何孝？孔子说：“当子女的要尽到孝），最不容易的就是对父母和颜悦色，仅仅是有了事情，儿女需要替父母去做，有了酒饭，让父母吃，难道能认为这样就可以算是孝了吗？“这是因材施教原则的体现。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b75|11", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 11, "q": "【2024年311真题8】下列选项中，名言与其所隐含的教学原则对应错误的是（", "opts": ["语之而不知，虽舍之可也一启发性原则", "不闻不若闻之，闻之不若见之一直观性原则", "杂施而不孙，则坏乱而不修—循序渐进原则", "见之不若知之，知之不若行之一理论联系实际原则"], "a": 0, "exp": "A选项出自《学记》，意思是如果老师开导了还是不懂，暂时放弃开导，也是可以的，与启发性原则不符，故本题选A选项。B选项出自《荀子》，意思是没有听到不如听到，听到不如看到，强调了直观行动对于获取真知的重要性，符合直观性原则。可收拾，体现了循序渐进原则的重要性。D选项出自《荀子》，意思是看到不如了解，了解不如实践，体现了理论联系实际原则的重要性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b75|12", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 12, "q": "【2024年311真题9】马卡连柯在高尔基工学团和提尔任斯基公社，探索出一套社会主义学校教育模式，特别强调平行教育原则。贯彻该原则的基本要求是（）", "opts": ["教育与生产劳动相结合", "集体教育与个别教育相结合", "在生产劳动中并且通过生产劳动教育学生集体", "以集体为教育对象，通过集体来教育学生个人"], "a": 3, "exp": "在培养学生集体方面，马卡连柯认为正确教育的方式应该设法不与个别人发生关系，而只与集体发生关系，通过集体教育每个个体。他把这种教育形式称为“平行教育原则”，D选项符合描述。A、C选项体现不出平行教育原则。B选项不符合马卡连柯认为的“正确的教育方式应设法不与个别人发生关系”，错误。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b75|13", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 13, "q": "【2025年311真题8】在数学课上，教师问学生：“假如从学校到你家有1000米远，那走剩下的一半呢？”….“也就是说，不管走多远，你都还要走剩下来的一半，是不是？”“是。”“照这么说，你永远也走不到家，是不是？”学生们都被逗笑了。教师顺势引出了“极限”问题。该教师所用的教学方法是（）", "opts": ["讲授法", "谈话法", "讨论法", "情境模拟法"], "a": 1, "exp": "B选项，谈话法是教师通过与学生面对面的问答、对话来引导学生思考、获取知识的方法。题干中教师围绕“走路剩距”连续提问，逐步引导学生发现矛盾、引出“极限”问题，符合谈话法“教师提问、学生回答”的特征，正确。A选项，讲授法以教师单向讲解、传递知识为主，几乎无师生互动问答，而题干核心是师生对话，并非教师单独讲授，错误。C选项，讨论法是学生之间围绕问题交流观点、共同探讨，题干中是教师主导的问答，无学生间的讨论互动，错误。D选项，情境模拟法须创设具体场景让学生模拟体验（如角色扮演、模拟操作）.题干仅通过问答展开，未设置模拟场景，错误。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b77|14", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 14, "q": "张老师讲《钱塘江大潮》时，利用多媒体播放钱塘江涨潮的壮观景色，为学生创设真实、具体、生动的场景，其教学方法是（", "opts": ["演示教学法", "现场教学法", "情境教学法", "示范教学法"], "a": 2, "exp": "张老师利用多媒体播放钱塘江涨潮的景色，为学生创设真实、具体、生动的场景，这属于情境教学法。通过创设具体的情境，让学生置身于真实的场景中，有助于提高他们的学习兴趣和理解能力。在这种情境下，学生更容易将所学知识与实际情境联系起来，加深对内容的理解和记忆。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b77|15", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 15, "q": "张老师在讲授散文《落花生）一课时，用多媒体播放作者及其姐弟几个买种子、翻地、播种、浇水、施肥等过程，为学生创设了真实、具体、生动的场景，还让学生谈谈做人该做花生这样的人，还是做苹果、石榴这样的人，大家各抒己见；张老师此处运用的教学法是（）", "opts": ["讨论法、示范教学法", "讨论法、情境教学法", "启发法、示范教学法", "启发法、情境教学法"], "a": 1, "exp": "张老师在讲授散文《落花生》一课时，通过多媒体播放作者及其姐弟几个种植花生的过程，并引导学生讨论做人的选择，运用的教学法是讨论法、情境教学法。讨", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b77|16", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 16, "q": "王老师在语文课上组织学生围绕课文《少年闯天下）中的人物形象，分组讨论该人物的性格特征和行为动机，通过角色扮演模拟人物之间的对话情景，最后各组上台表演，全班评议各组的表演效果。这堂课王老师使用的教学方法是（", "opts": ["情境教学法、讨论教学法、实践扮演法", "讲授教学法、实践教学法、讨论教学法", "讨论教学法、角色扮演法、实践教学法", "讨论教学法、情境教学法、角色扮演法"], "a": 3, "exp": "学生围绕人物形象讨论，使用的是讨论教学法。学生扮演人物对话，使用的是角色扮演法。模拟人物对话情景，使用的是情境教学法。事物和现象产生变化，进行观察和分析，以获得知识和技能的方法。B选项，演示法是指通过展示实物、直观教具，进行示范性的实验或采取现代化视听手段等指导学生获得知识或巩固知识的方法。C选项，练习法是学生在教师的指导下运用所学知识独立地进行实际操作，以巩固知识、形成技能的方法。D.选项，参观法是教师根据教学目的和要求，组织学生对实物进行实地观察、研究，从而在实际中获得新知识或巩固、验证已学知识的方法。老师带学生去看花，并讲解如何区分雄蕊与蕊等知识，采用的是参观法。故本题选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b78|17", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 17, "q": "数学课上，张老师在教“圆周率”时，向学生介绍了祖冲之的成长过程以及他与圆周率的故事。张老师遵循的教学原则是（", "opts": ["直观性原则", "巩固性原则", "循序渐进原则", "科学性与思想性统一原则"], "a": 3, "exp": "本题考查的知识点是教学原则。D选项，科学性与思想性统一原则是指以马克思主义为指导，把现代先进科学的基础知识和基本技能传授给学生，同时要结合知识、技能中内在的道德因素，对学生进行政治、思想教育和道德品质教育。题干中张老背后的德育因素，体现了科学性与思想性统一原则。故D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b78|18", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 18, "q": "小学数学老师在教除法时是这样设计的：“如果有12个馒头，每人吃了3个，能够分给的教学原则是(", "opts": ["科学性与思想性相统一原则", "理论联系实际原则", "巩固性原则", "量力性原则"], "a": 1, "exp": "本题考查的知识点是理论联系实际教学原则。B选项，理论联系实际原则是指教学要以学习基础知识为主导，从理论与实际的联系上去理解知识，注意运用知识去分析和解决问题。本题中的老师把除法与实际生活中的分馒头联系起来，帮助学生理解知识，是贯彻了理论联系实际的教学原则，B选项正确。·第七章教学", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b78|19", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 19, "q": "复观察，以理解“棱”“长”“宽”“高”等相关概念。这位教师的做法主要体现的教学原则是(", "opts": ["循序渐进原则", "启发诱导原则", "直观性原则", "量力性原则"], "a": 2, "exp": "直观性教学原则是指教师运用学生的多种感官与已知经验，通过各种形式的感知，丰富学生的直接经验和感性认识，使学生获得生动的表象，从而全面地掌握知识。题干中老师让学生从不同角度观察长方体的盒子，理解什么是“棱”“长”“宽”“高”，是教师利用学生的感官，丰富学生的直接经验和感性认识，从而全面地掌握知识的表现，让学生在大脑里面对“棱”“长”“宽”“高”有一个清晰的表象认识，满足直观性教学原则的定义。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b78|20", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 20, "q": "语文老师在讲生字“灭”的时候，在一个透明的玻璃杯里点燃一根蜡烛，然后在杯口盖上一块玻璃，火渐渐地熄灭了。这样的教学方法是（", "opts": ["讲授法", "实验法", "演示法", "练习法"], "a": 2, "exp": "题干中，语文老师通过一个简单的现象演示，使学生通过观察获得了对“灭”字的形象认识，属于演示法。本题易错选B选项，题干中的实验由教师完成，目的是体现“灭”字的特点，不存在对实验现象、实验原理的分析，不属于实验法，故排除B选项。A、D两项与题意无关，排除。故本题答案为C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b78|21", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 21, "q": "孟子提出“盈科而进”，体现的教学原则是（", "opts": ["因材施教", "循序渐进", "理论与实践相结合", "科学性与思想性相结合"], "a": 1, "exp": "题干中“盈科而进”的原意是流水在前进的过程中，要填满每一个坑洼后才能继续向前，比喻要想进步、提高，必须打好坚实的基础，体现的教学原则是循序渐进，故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b78|22", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 22, "q": "中学生物老师在讲到“遗传与进化”这一部分时，讲述了袁隆平面对当时社会的严重饥荒，立志用农业科学技术帮助世界人民不再受饥饿威胁，培育杂交水稻的事迹，同学们深受教育。这体现的教学原则是（", "opts": ["直观性原则", "启发性原则", "理论联系实际的原则", "科学性与思想性相结合的原则"], "a": 3, "exp": "科学性与思想性相结合的原则指既要把现代先进科学的基础知识和基本技能传授给学生，同时要结合知识、技能中内在的德育因素，对学生进行政治、思想教育和道德品质教育。中学生物老师在讲到“遗传与进化”这一部分时，讲述了袁隆平的事迹，使同学们深受“教育”，体现了科学性与思想性相结合的原则。教学模式", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b79|23", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 23, "q": "【2010年311真题9】教学过程由四个阶段组成：闸明“个”的阶段，闸明“类”的阶段，掌握规律与范畴的阶段，获得世界经验与生活经验的阶段。这种教学模式属于(", "opts": ["发现教学模式", "掌握学习模式", "范例教学模式", "非指导性教学模式"], "a": 2, "exp": "C选项“范例教学模式”认为教学过程是由“个”案到“类”案，掌握规律，获得经验的过程。强调通过一定方法，让每个学生掌握知识。D选项“非指导性教学模式”强调教学要以学生个人为中心，教师促进学生学习，而非“教”学生学习。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b79|24", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 24, "q": "【2017年311真题8】学习者中心课程理论的拥护者，在教学模式上更倾向于选择(", "opts": ["程序教学模式", "掌握教学模式", "探究教学模式", "范例教学模式"], "a": 2, "exp": "学习者中心课程理论强调以学生的活动为中心，培养其社会实践能力。在教学模式上，它更倾向于选择探究教学模式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b79|25", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 25, "q": "【2020年311真题10】让学生从选择出来的有限例子中主动获得本质的、结构性的、原则性的、典型的知识、能力和态度，这种教学模式是（", "opts": ["发现教学模式", "掌握学习教学模式", "范例教学模式", "非指导性教学模式"], "a": 2, "exp": "由题干中强调“例子”可知，此为范例教学模式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b81|26", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 26, "q": "研究表明，在学习新的内容时，人的左右脑并用，比只用一边的效果好。以下哪种教学模式应用了这样的规律（", "opts": ["暗示教学模式", "发现教学模式", "掌握教学模式", "逆向教学模式"], "a": 0, "exp": "左右脑分工不同，学习新内容时，左右脑并用，是为了利用暗示教学，进行潜移默化的影响。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b81|27", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 27, "q": "目标教学法是教师围绕教学目标展开一系列教学活动，并以此来激发学生的学习兴趣与积极性，激励学生为实现教学目标而努力学习的方法。目标教学法体现的思想观点是(", "opts": ["哲学取向", "认知主义", "行为主义", "建构主义"], "a": 2, "exp": "目标教学法体现的思想观点是行为主义。这种教学方法强调通过设定明确的教学目标来引导学生的学习，激发他们的学习兴趣和积极性，促使他们为实现这些目标而努力学习。行为主义认为学习是对外部刺激做出反应的过程，目标教学法正是基于这一观点设计的教学方法。7言936378883.【答案】B根据题干描述，布卢姆主张的学习类型是掌握学习。这种学习类型强调手段来促进学习，同时通过形成性评价来掌握学习进展，以满足不同学生的学习需求。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b82|28", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 28, "q": "发现教学模式倡导学生独立发现问题、解决问题、实现认知的过程，强调学生是学习的）主体，这一教学模式的提出者是（", "opts": ["奥苏伯尔", "布鲁纳", "苛勒", "瓦·根舍因"], "a": 1, "exp": "本题考查的是常见的教学模式。引导一发现教学模式又叫问题一探究教学模式，是指教学活动以解决问题为中心，学生在教师指导下发现问题、提出问题并通过自己的活动找到答案的一种教学模式。该模式多见于数理学科的教学，由美国认知学派心理学家布鲁纳提出。故本题正确答案为B选项。A选项，奥苏伯尔提出有意义学习的观点，认为有意义学习的实质是将新知识与已有知识建立起非人为（内在的）的和实质性（非字面）的联系。C选项，苛勒提出完形一顿悟说。他认为学习是通过顿悟过程实现的，学习是个体利用本身的智慧与理解力对情境及情境与自身关系的顿悟，而不是动作的累积或盲目的尝试。学习的实质是在主体内部构造完形。D选项，德国教育家瓦·根舍因创造了范例教学法。范例教学法是指教师通过对教材中的典型事例进行分析，使学生掌握科学知识和科学方法的一种教学方法。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b82|29", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 29, "q": "教英语的方老师在教学前都会给学生下达学习任务，并就任务进行书面和口头测试，要求学生达到80%以上的正确率。对于没有达到要求的学生，他还会为其提供额外的练习。方老师的做法属于个别化教学模式中的（）", "opts": ["个别辅导", "掌握学习", "程序教学", "适应性教学"], "a": 1, "exp": "本题考查的知识点是布卢姆的掌握学习理论。掌握学习是在学习新内容之前，确保所有的或几乎所有的学生对某一确定技能的学习都达到预定的掌握水平。题干中，要求学生的正确率达到80%以上，且没达到的还会为其提供额外的练习，符合掌握学习模式。因此B选项符合题意。教学过程", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b84|30", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 30, "q": "【2010年311真题10】为了达到一定的教学目的，对教学内容、组织、方法及媒体的使用等所进行的系统规划称为（）", "opts": ["教学策略", "教学模式", "教学目标", "教学设计"], "a": 3, "exp": "教学设计是为了达到一定的教学目的，对教学内容、组织、方法及媒体的使用等进行的系统规划。其实质是备课的过程，备课要备学生、备教材、备教法。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b84|31", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 31, "q": "【2017年311真题11】“形式教育论”认为，教育应发展人的能力。这个“能力”是指）(", "opts": ["实践能力", "创新能力", "理性思维能力", "解决实际问题能力"], "a": 2, "exp": "形式教育论强调教育应发展人的理性思维能力；实质教育论强调教育应引导学生掌握知识。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b84|32", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 32, "q": "【2023年311真题12】俞子夷在回顾自己辅导某学生算学的经历时写道：“他不但信我，和我接近，待我好，他常在别人面前自夸；他最得意的是我教他。他起先或者以为我不肯教他，不屑教他。后来渐渐和我接近，知道我的确是他的朋友，帮助他克服了好多算学上的困难。他是孩子，所以很天真地信仰我，所以无论说什么话都是听从的。（<教算一得))这段经历表明,教学过程中应处理好（）", "opts": ["间接经验与直接经验的关系", "掌握知识与发展智力的关系", "智力因素与非智力因素的关系", "教学方式与教学内容的关系"], "a": 2, "exp": "非智力活动是指在认知事物、掌握知识过程中诱发的好奇、欲望、兴趣、情感、意志和性格等非智力因素的活动。确是他的朋友”，再到最终在“我”的帮助下“克服了好多算学上的困难”，学生在学习过程中情感的变化体现了非智力因素对教学的影响。因此，在教学活动中必须处理好智力因素与非智力因素的关系。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b84|33", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 33, "q": "【2025年311真题11】新时代大力弘扬教育家精神，引导教师努力成长为有理想信念、有道德情操、有扎实学识、有仁爱之心的好老师，做学生锤炼品格、学习知识、创新思维、奉献祖国的引路人，成为塑造学生品格、品行、品位的大先生。这要求教师在教学过程中要特别处理好（", "opts": ["间接经验与直接经验的关系", "掌握知识与培养思想品德的关系", "教学方式与教学内容的关系", "掌握知识与提高能力的关系"], "a": 1, "exp": "题干核心是弘扬教育家精神，要求教师成为“四有”好老师、“引路人”、学中“思想品德培养”的重要性。这与B选项“掌握知识与培养思想品德的关系”对应，即教学须兼顾知识传授与品德培养。A选项，间接经验与直接经验的关系，侧重知识获取的两种途径（如课本知识与实践验），与题干强调的“品格塑造、理想信念”无关，错误。品德培养”这一核心要求，错误。D选项，掌握知识与提高能力的关系，聚焦知识学习与能力（如思维、实践能力)提升的关联，不涉及题干中的“道德情操、锤炼品格”，错误。二、分析论述题【解析】第一问是存在的问题，可以从多角度进行分析，如作业的数量、质量、目的、形式和结果等。第二问是问题导致的后果，同样可以从多角度进行分析，如对学生的身体、智力和心理等方面的影响。第三问是改进建议，需要结合第一问的内容，从作业的数量和质量等角度进行分析。【参考答案】(1）存在的问题：①作业量大、消耗时间长，学生课业负担重。②作业的目的狭隘，仅仅为巩固书本知识、应试而做作业。③作业的内容大多以书本知识为中心，过分强调具有标准答案的封闭式作业。相当的作业意义大微信93637888（2）可能的后果：①学生厌学，求知欲下降。②不仅没有促进学生智力的发展，反而阻碍学生智力的发展。③养成迷信权威、迷信书本的习惯，学生批判性思维能力下降。④用一个模子塑造学生，束缚了学生的个性发展。③学生长期伏案作业，缺乏体育锻炼，导致身体健康受损。（3）改进建议：①精选作业，做到“少而精”。②既可以为巩固书本知识而布置作业，也可以为学习新知识、发现和探索知识布置作业。③多布置一些应用型、拓展型作业，引导学生将书本知识在生活情境中加以应用。④布置具有适度挑战性的作业。③布置动手操作、调查研究、表演和自主探究型的作业。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b86|34", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 34, "q": "【2011年311真题9】将一个班的学生按能力分组，各组以不同的进度完成相同的课业。这种能力分组属于（", "opts": ["作业分组制", "活动分组制", "异质分组制", "混合能力分组制"], "a": 0, "exp": "将全校学生一分为二，上午一部分在教室上课，另一部分则在体育场、图书馆、工厂、商店以及其他场所活动，下午对调，这种方式属于二部制。工读制指的是半工半读的方式，而题干中学生在工厂、商店这些地方，并不是以员工的身份活动，更多的两个或两个以上年级的学生合编成一班由一位教师用不同的教材在同一节课里对不同年级的学生进行教学。合作教学指的是小组合作。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b86|35", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 35, "q": "【2011年311真题13】某山区小学，每个年级数学、语文等科的教学均由一名教师担后续关注公众号【研大]任。这些教师属于（", "opts": ["兼任教师", "主任教师", "级任教师", "科任教师"], "a": 2, "exp": "题干描述的教学方式是复式教学，负责一个年级全部或主要课程教学的教师属于级任教师。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b86|36", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 36, "q": "【2013年311真题8】学生围绕自己和教师订立的学习契约开展自学和独立作业的教学组织形式是(", "opts": ["文纳特卡制", "道尔顿制", "特朗普制", "曼海姆制"], "a": 1, "exp": "围绕订立的契约开展自学和独立作业的教学组织形式是道尔顿制。道尔顿制的关键词有自由和合作、公约、各科实验室。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b86|37", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 37, "q": "【2015年311真题13】研究表明，人的发展存在个体差异，充分尊重和利用这种发展特点的教育措施有（", "opts": ["个别辅导、分层教学、小组合作学习", "个别辅导、分层教学、班级授课", "分层教学、班级授课、小组合作学习", "班级授课、小组合作学习、个别辅导"], "a": 0, "exp": "人的发展存在个体差异，为了针对这种差异开展教学，可以采用个别辅导、分层教学和小组合作学习的教学方法。班级授课制容易忽略个体差异，故排除。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b86|38", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 38, "q": "【2018年311真题8】近代以来，人们设计出一些力图克服班级授课制局限性，同时保持其优越性的新型教学组织形式，主要有（", "opts": ["分层教学、个别教学、小队教学", "个别教学、小组合作学习、分层教学", "小组合作学习、小队教学、个别教学", "分层教学、小组合作学习、小队教学"], "a": 3, "exp": "本题解题的关键在于了解班级授课制的局限性和优越性分别是什么。其局限性是不能做到因材施教，优越性是相对于个别教学而言的，较为便捷、高效。本题使用排除法，直接排除“个别教学”即可，答案为D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b89|39", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 39, "q": "“君子深造之以道，欲其自得之也。自得之，则居之安；居之安，则资之深；资之深，则取之左右逢其原”说明了（）的重要性", "opts": ["自主学习", "合作学习", "小组学习", "实践学习"], "a": 0, "exp": "“君子深造之以道，欲其自得之也。自得之，则居之安；居之安，则资之深；资之深，则取之左右逢其原”这句话强调一个人要自主地去学习和探索，真正地理解和掌握知识，才能运用自如。自主学习是学生凭借自己的能力，积极主动地进行学习的过程。B选项“合作学习”是学生在小组环境中相互合作，实现共同学习目标的学习方式。C选项“小组学习”是在小组环境中进行的学习方式。D选项“实践学习”是在实践中获得经验的学习方式。综上，这句话体现了自主学习的重要性。因此，答案为A。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b89|40", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 40, "q": "以下关于大班教学说法正确的是（", "opts": ["有利于尊重个性，发展个性", "能体现以学习者为中心的理念", "符合现代教育开放的潮流", "学生与教师交流的时间与次数有限"], "a": 3, "exp": "本题考查班级授课制的优缺点。大班教学是教师中心的体现，与班级授课制的优缺点相同。班级授课制的优点：①有严格的制度保证教学的正常开展，达到一定质量；②有利于大面积培养人才；③能够充分发挥教师的主导作用；④有利于发挥集体教育的作用。班级授课制的不足：①难以因材施教；②难以形成学生的探索精", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b89|41", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 41, "q": "在班级组织改革尝试中有一种特朗普制,其特点是（）", "opts": ["小班上课，大班讨论，个人独立研究", "大班上课，小班讨论，个人独立研究", "大班上课，小班讨论，小组合作研究", "小班上课，大班讨论，小组合作研究"], "a": 1, "exp": "本题考查的知识点是教学组织形式。特朗普制又称“灵活的课程表”，由教育学教授劳伊德·特朗普提出。其基本做法是，把大班上课、小班讨论、个人独立研究结合在一起。大班是所有学生一起上课；小班是把大班的学生分为20人左右的小组，研究和讨论大班授课材料；个别教学是由学生独立完成作业也就是选项中的独立研究。特朗普制既具有班级授课制的优点，也有个别教学的长处，但管理起来比较麻烦。A、C、D三项属于干扰项，均与题意不符合。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b91|42", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 42, "q": "【2009年311真题8】班主任在与小明谈话时说：“根据前段时间你的表现，虽然学习效果不是很理想，但非常努力，如果注意改进学习方法，相信成绩会不断提高。”其中的评价属于（）", "opts": ["配置性评价", "形成性评价", "终结性评价", "鉴定性评价"], "a": 1, "exp": "本题解题的关键在于班主任虽然评价了小明的表现，但更指出了其改进学习方法有助于未来的发展，评价的目的是鼓励小明后续的学习，属于过程中的评价，为形成性评价。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b92|43", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 43, "q": "【2015年311真题8】主要用来描述和反映学生的进步状况，强调学生对作品的自我评估与反思,适合对学生长程学习、深层学习结果进行评价的是（）", "opts": ["纸笔测验", "表现性评价", "真实性评价", "档案袋评价"], "a": 3, "exp": "档案袋评价是对学生的追踪性评价。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b92|44", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 44, "q": "【2022年311真题9】罗伯特·斯莱文教授倡导过多种形式的小组合作学习，其中“学生小组成绩划分法（STAD）在学业评价上采取的主要措施是（", "opts": ["与前次成绩相比较计算学生的提高分，以全组提高分总和作为小组学习成绩", "将学生测验的原始成绩转化为标准分，以全组标准分总和作为小组学习成绩", "各组之间开展一对一的学习竞赛，根据胜负场次对各组进行排名", "各组各自合作完成一份作业，据此评定各组学习成绩"], "a": 0, "exp": "诊断性评价、形成性评价和终结性评价是根据评价在教学中的作用（评价目的）不同进行划分的。诊断性评价是为了评估学生现有的知识和能力发展情况；形成性评价是为了使教师与学生都能及时获得反馈信息，促进学生当前的学习，提高教学质量；终结性评价是为了评价一定阶段学生的学习成绩。教授创设的，其基本教学程序是：导学人境，呈现教学目标；小组学习；达标测验；计算分数；小组得到认可。通过教学实践，小组合作学习不仅能改善课堂教学气氛，提高教学成绩，而且能促进学生形成良好的非认知品质。（1）导学入境，呈现教学目标。在小组合作学习之前，先由教师向学生讲授基础知识，提供给学生小组合作学习所需要的背景知识材料以及需要解决的问题及本小组所要承担的任务等。(2)小组学习。在STAD中，小组是最主要的特征和最主要的组织形式，一般宜采用4人小组，STAD在进行小组组建时，应注意小组构成成员应是一个班级集体的缩影，每个小组通常包括一名成绩好的学生、一名成绩差的学生和两个成绩中等的学生，基本保证全班各小组的学生平均成绩大致相同。每一个小组成员都分担一定的学习任务，承担对本小组团体成绩高低的责任，即每一个小组成员的成绩都将决定团体成绩的高低。（3）达标测验。测验学生对所学内容的掌握情况，要及时对学生应掌握的课程内容进行强化，并通过测验反馈出教师在课堂讲授和小组合作学习中的不足之处。(4)计算分数。奖励。（5）小组得到认可。教师对取得好的成绩的小组及时给予表扬与奖励。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b94|45", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 45, "q": "教育评价更直接地指向方案的活动而非方案的内容，满足评价能听取人对信息的需求，在反映方案得失长短的评价报告中反映人们不同的价值观念，这种评价模式为(", "opts": ["CIPP评价模式", "目标游离评价模式", "应答模式", "反对者模式"], "a": 2, "exp": "听取不同人的意见的教学评价模式为应答模式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b94|46", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 46, "q": "不属于教学评价的教育性功能的是（", "opts": ["具有鉴别质量、区分优劣、选拔安置的作用", "为教学活动的有序进行提供反馈信息", "可以激发教师和学生的行为动力", "本身具有教学和发展性"], "a": 0, "exp": "选项“具有鉴别质量、区分优劣、选拔安置的作用”。教学评价的教育性功能主要包括为教学活动提供反馈信息（B选项）激发教师和学生的行为动力（C选项），以及本身具有教学和发展性（D选项）。虽然教学评价可以帮助鉴别质量和区分优劣，但这种选拔和安置的作用并不是教学评价的主要教育性功能。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b94|47", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 47, "q": "王老师告诉陈浩妈妈，陈浩期中语文测试成绩在班上属于中等水平，这种评价属于什么（）", "opts": ["绝对性评价", "相对性评价", "内部评价", "个体内差异评价"], "a": 1, "exp": "本题考查的知识点是教学评价的类型。A选项，绝对性评价又称为目标参照性评价，是运用目标参照性测验对学生的学习成绩进行的评价。它主要依据教学目标和教材编制试题来测量学生的学业成绩，判断学生是否达到了教学目标的要求，而不以评定学生之间的差异为目的。B选项，相对性评价又称为常模参照性评价，是运用常模参照性测验对学生的学习成绩进行的评价。它主要依据学生个人的学习成绩在该班学生成绩序列或常模中所处的位置来评价和决定他的成绩的优劣，而不考虑他是否达到教学目标的要求。C选项，内部评价也就是自我评价，指由课程设计者或使用者自己实施的评价。D选项，个体内差异评价是对被评价者的过去和现在进行比较，或将评价对象的不同方面进行比较。“陈浩期中语文测试成绩在班上属于中等水平”属于运用常模参照测验对学生的学习成绩进行的评价，故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b94|48", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 48, "q": "高一新生人学时一般会进行摸底分班测验，这种测验属于（", "opts": ["诊断性评价", "形成性评价", "总结性评价", "过程性评价"], "a": 0, "exp": "A选项，诊断性评价是在学期开始或一个单元教学开始时，为了了解学生的学习准备状况及影响学习的因素而进行的评价。题干描述的摸底考试就是一种诊断性评价。B选项，形成性评价也称为过程性评价，是在教学过程中为改进和完善教学活动而进行的对学生学习过程及结果的评价。C选项，总结性评价是在一个大的学习阶段、一个学期或一门课程结束时对学生学习结果的评价，也称为终结性评价。D选项，过程性评价是在教育、教学活动的计划实施的过程中，为了解动态过程的效果，及时反馈信息，及时调节，使计划、方案不断完善，以便顺利达到预期的目的而进行的评价。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b94|49", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 49, "q": "期中考试后，吴老师在分析试卷时发现学生在某一知识点上失分比较多，于是对自己的教学进行了反思，并作出调整。这说明教育评价具有（", "opts": ["导向功能", "选择功能", "反馈功能", "强化功能"], "a": 2, "exp": "A选项，教育评价的导向功能认为，教育评价是根据教育方针和教育目标的要求，编制出各种评价的指标，较为全面地衡量学校和地区的教育工作，目的在于保证教育工作不至于偏离方向，使教育方针和教育目标得以全面地贯彻和实现。B选项，教育评价的选择功能认为，通过教育评价能对学生在知识掌握和能力发展方面的", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b94|50", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 50, "q": "小明期末考试数学没考好，妈妈批评了他，他对妈妈说：“我比上次考得好，上次我都没有及格，这一次我及格了。”小明对自己这次数学考试的评价属于（", "opts": ["绝对性评价", "综合评价", "诊断性评价", "个体内差异评价"], "a": 3, "exp": "本题考查的知识点是教学评价。A选项，绝对性评价又称为目标参照性评价，是运用目标参照性测验对学生的学习成绩进行的评价。A选项不符合题意。B选项，综合评价是指综合多种评价方式进行的评价。B选项不符合题意。C选项，诊断性评价是在学期开始或一个单元教学开始时，为了了解学生的学习准备状况及影响学习的因素而进行的评价。C选项不符合题意。D选项，个体内差异评价是对被评价者的过去和现在进行比较，或将评价对象不同方面进行比较。D选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-07|b94|51", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-07", "chName": "", "sec": "基础练习", "no": 51, "q": "在二年级数学“元、角、分”单元的教学后，杨老师布置的课后作业是“到文具店买文具”。关于杨老师的做法，下列说法错误的是（", "opts": ["有助于学生运算能力的培养", "有于“双减”政策的具体要求", "帮助学生体会数学与生活之间的联系", "符合《义务教育数学课程标准》的要求"], "a": 1, "exp": "，“双减”政策的含义是有效减轻义务教育阶段学生过重的作业负担和校外培训负担。“双减”政策明确规定：提高作业设计质量。发挥作业诊断、巩固、学情分析等功能，将作业设计纳人教研体系，系统设计符合年龄特点和学习规律、体现素质教育导向的基础性作业。鼓励布置分层、弹性和个性化作业，坚决克服机械、无效作业，杜绝重复性、惩罚性作业。杨老师布置的课后作业是“到文具店买文具”，符合“双减”政策的具体要求。二、材料分析题【参考答案】（1）教育评价的功能包括：①诊断教学问题：教育评价可以帮助老师判断存在哪些教学问题，如教学内容设置是否合理、教学方法是否恰当等。②提供反馈信息：通过教育评价可以让教师、学生及管理部门了解教与学的真实情况，看到存在的差距和不足。③调控教学方向：教育评价结果可以帮助教师调整教学计划和方式，使之更好地达成教学目标。④检验教学效果：教育评价可以检查教学达成的具体效果，看教学活动是否达到预期目标。（2）在终身教育理念下，教育被看成一个连续的过程，而不仅仅是某些阶段中的关键考试。这需要教育评价进行相应地改革：①更加注重过程性评价，不仅有定期考试，也需要对平时的学习过程进行评价，以便及时发现问题并改进。②评价要强调个人成长，不应仅以某次考试成绩断定一个人的教育结果。要看到每个人从不同起点出发，取得的进步。③失败不应被污名化，还有改正的机会。评价不能简单地淘汰失败者，而应鼓励其进步。通过这些改革，教育评价才能在终身教育过程中更好地发挥诊断、反馈、调整和鼓励的作用。（3）在教学过程中，教师应该：第一，关注每个学生的个别起点，而不进行简单的结果对比；第二，重视过程评价，及时了解学生在学习过程中的问题和进步；第三，使用多种评价方式，不仅仅依赖考试结果；第四，提供个性化指导和鼓励，帮助每个学生进步；第五，发挥评价的诊断和反馈功能，及时调整教学策略。只有做到这些，教师才能让评价真正帮助每位学生成长，而不是简单地淘汰。后续关注公众号[研大]永久微信1931637888", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b97|1", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 1, "q": "【2017年311真题12】科尔伯格主张用“道德两难法”来促进学生的（", "opts": ["道德认知发展", "道德情感发展", "道德意志发展", "道德品格发展"], "a": 0, "exp": "科尔伯格主张用“道德两难法”来促进学生的道德认知发展。道德两难是指一个人在决策中面临两个或两个以上的道德准则或价值观之间的冲突，无论做出什么样的决定都有可能侵犯某个价值观。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b97|2", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 2, "q": "【2023年311真题9】科尔伯格及其团队在运用道德两难故事促进学生道德判断发展的实践中，研发了一系列围绕两难故事的提问和追问策略。其中，引发学生内部道德认知发生冲突的关键策略是（", "opts": ["突出道德争端的提问", "突出相邻阶段论证的提问", "争端间追问", "普遍后果追问"], "a": 1, "exp": "科尔伯格认为，学生的道德发展要从一个阶段迁移到下一个阶段，需要经历道德认知的内在冲突和重新组织。为了引发这种冲突，科尔伯格使用了“突出相邻阶段论证的提问”策略。具体做法是，在学生提出某一道德观点后，教师接着提出一个稍高一级的道德观点，让学生比较和对照两个观点之间的区别。这种对比会使学生意识到自己观点的不足之处，从而产生认知失衡。为了减轻这种不平衡状态，学生的道德认知会进行重组和转变，最终迁移到新的发展阶段。所以，引发学生内部道德认知发生冲突的关键策略是B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b97|3", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 3, "q": "【2025年311真题9】在一次反校园欺凌班会上，学生们谈及正义问题。甲生坚持伸张报应性正义，惩罚那些特强凌弱者，他们伤害同伴有多严重就该受多重的惩罚。乙生力主伸张修复性正义，一方面坚持欺凌者必须改正错误，向受害同学赔礼道歉，弥补过失，对所造成的伤害和破坏承担起修复责任；另一方面主张受伤害的同学宽恕已经真诚道歉并且完成修复责任的同学，给予欺凌者以悔过自新的机会，最终双方恢复正常的同学关系。根据科尔伯格的道德发展理论，甲生和乙生所处的道德发展阶段分别是（）", "opts": ["第一阶段和第四阶段", "第二阶段和第三阶段", "第三阶段和第四阶段", "第四阶段和第六阶段"], "a": 1, "exp": "科尔伯格道德发展理论的三水平六阶段如下：儿童只根据后果来判断行为的好坏，为了免遭惩罚而听服从和惩罚的定向阶段从权威人物的命令，尚未具有真正意义上的准则概念。前习俗水平(0~9岁)工具性相对主义以个人的最大利益为出发点来考虑是否遵守规则，通常的定向阶段是为了获得奖赏或满足自己的需要而尊重规则。儿童在进行道德评价时总是考虑到他人和社会对一人际协调的定向科尔阶段（好孩子定个“好孩子”的期望和要求，并以此为标准开展思维和伯格的习俗水平行动。向阶段）道德(9~15岁)发展儿童更加广泛地注意到维护普遍的社会秩序的重要性，维护权威或秩序理论的定向阶段履行个人责任，尊重权威，强调对法律和权威的服从。社会契约的定向个体认识到规则是人为的、民主的、契约性的东西，当社阶段会习俗或法律不符合公众利益时就应该修改。后习俗水平（15岁以后）普遍道德原则的个体已经意识到社会规则和法律的局限性，开始基于自定向阶段己的良心或人类的普遍价值标准判断道德行为。甲生：第二阶段第二阶段的核心逻辑是等价交换，关注惩罚与伤害匹配的功利性公平。甲生主张伤害多严重就受多重惩罚，符合这一阶段的特征。乙生：第三阶段第三阶段的核心是维护人际关系和谐、获得他人认可。乙生强调赔礼道歉、宽恕和恢复同学关系，符合这一阶段的特征。第一阶段关注避免惩罚，第四阶段聚焦遵守规则，第六阶段关注抽象伦理原则，均与甲生和乙生主张不符，故排除A、C、D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b99|4", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 4, "q": "胖虎是学校初二年级的学生，老师发现他在学校里偷偷吸烟。经过老师的教育，胖虎认识到了吸烟的坏处，表示再也不吸烟了。后来老师又多次发现他在学校厕所或校园周围吸烟，每次询问他，胖虎都说自己确实不想吸烟但就是忍不住。针对这种情况，老师最应该对其从哪方面进行教育？（）", "opts": ["道德认识", "道德行为", "道德意志", "道德情感"], "a": 2, "exp": "本题考查的知识点是德育过程的基本规律。学生的思想品德是知、情、意、行的统一体。C选项，道德意志是个体自觉地调节道德行为、克服困难，以实现预定道德目标的心理过程。胖虎忍不住吸烟的原因在于道德意志的薄弱。故C选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b99|5", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 5, "q": "古人云“唯仁者能好人，能恶人”。这属于德育过程中的（）", "opts": ["道德认识", "道德情感", "道德意志", "道德作为"], "a": 1, "exp": "题干中，“唯仁者能好人，能恶人”的意思是只有那些有仁德的人能够公正地喜欢别人，能够公正地厌恶别人。这句话指的是人因自己的认识而产生对其他人的喜欢或厌恶的体验，属于道德情感。故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b99|6", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 6, "q": "王守仁明确提出，“今教童子”必须“讽之读书，以开其知觉”。这表明，在德育过程中,教师要重视学生（", "opts": ["道德认识的提高", "道德情感的发展", "道德意志的锻炼", "道德行为的训练"], "a": 0, "exp": "题干中，“今教童子”必须“讽之读书，以开其知觉”的意思是教导儿童应用读书为内容来劝告他们、开拓他们的智能。这表明在德育过程中，教师要重视学生道德认识的提高。因此，A选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b101|7", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 7, "q": "【2008年311真题10】小明目睹欺负弱小的同学经常受到老师的严厉批评、处罚，而那些爱护弱小的同学则受到大家的喜爱。久而久之，他也变成了一个乐于助人、不欺", "opts": ["亲历学习", "观察学习", "", "试误学习迁移学习"], "a": 1, "exp": "本题解题的关键在于小明看到了不同行为的后果，选择了其中好的行为进行学习。这属于观察学习和间接强化。A选项“亲历学习”注重的是学生的直接经验。C选项“迁移学习”指的是一种学习对另一种学习的影响。D选项“试误学习”由桑代克提出，是指学习的过程是一种渐进的尝试错误的过程。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b101|8", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 8, "q": "【2018年311真题9】在“海因茨偷药”的道德两难问题上，某儿童认为：“不管妻子过去对他好不好，他都要对妻子负责。为救妻子去偷药，只不过做了丈夫该做的事。如果他不这样做，别人会骂他的。”根据科尔伯格道德认知发展阶段理论，该儿童道德判断的特点是（", "opts": ["以人际和谐或“好孩子”为定向", "以工具理性的相对主义为定向", "以惩罚与服从为定向", "以法律的秩序为定向"], "a": 0, "exp": "本题解题的关键在于“如果他不这样做，别人会骂他的”，证明儿童在意他人对自身行为的评价，这属于以人际和谐或“好孩子”为定向的阶段。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b101|9", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 9, "q": "【2021年311真题12】下列格言中，体现了自我教育法的是（）", "opts": ["省察于将发之际，省察于已发之后", "纸上得来终觉浅，绝知此事要躬行", "染于苍则苍，染于黄则黄", "桃李不言，下自成蹊"], "a": 0, "exp": "A选项注重自我省察，强调的是自我教育。B选项强调实践的重要性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|10", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 10, "q": "对中小学生来说，通过群体规定比个别劝说更有助于其培养良好的态度和品质，这体现的德育方法是（）", "opts": ["集体教育法", "榜样示范法", "自我教育法", "说服教育法"], "a": 0, "exp": "教育法。通过群体规定和约束，学生在集体中形成共同的行为准则和规范，从而促进他们培养良好的态度和品质。集体教育法强调集体的力量和规范对学生行为和品德的影响，通过集体的力量引导学生形成正确的行为习惯和品德观念。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|11", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 11, "q": "德育的知行统一原则要求（", "opts": ["理论重于实践", "实践重于理论", "学习与理论相结合", "理论与实践相结合"], "a": 3, "exp": "本题考查的知识点是德育原则。知行统一原则是指德育既要重视思想道德的理论教育，又要重视组织学生参加实践锻炼，把提高认识和行为养成结合起来，使学生做到言行一致、表里如一。综上所述，知行统一原则要求理论与实践相结合，故本题答案选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|12", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 12, "q": "古代学者朱认为“论先后，知为先；论轻重，行为重”，这体现的德育原则是（）", "opts": ["一致性原则", "正面引导原则", "知行统一原则", "严格要求原则"], "a": 2, "exp": "本题考查的知识点是德育原则。知行统一原则指既要重视思想道德的理论教育，又要重视组织学生参加实践锻炼，把提高认识和行为养成结合起来，使学生做到言行一致、表里如一。“论先后，知为先；论轻重，行为重”指的是知道与行动之间，若考虑其先后顺序的话，应先知道；若考虑谁更重要的话，则行为、实践更加重要。这与知行统一原则的观点一致。因此，本题正确答案为C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|13", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 13, "q": "《论语》中记载的“夫子循循然善诱人，博我以文，约我以礼，欲罢不能。”反映的德育原则是（）", "opts": ["疏导原则", "集体教育原则", "理论与生活相结合原则", "教育影响一致性和连贯性原则"], "a": 0, "exp": "“夫子循循然善诱人，博我以文，约我以礼，欲罢不能”的意思是老师善于一步步引导和教育我们，用渊博的文献知识来使我们有文采，用礼仪制度来约束教导我们，使我们想停止都不可能。符合疏导原则的含义。故本题选A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|14", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 14, "q": "阿亮痴迷网络无法自拔，李老师找阿亮谈心，聊互联网和比尔·盖茨，并肯定他上网学习电脑技术的积极性，借此了解了阿亮的内心世界，在此基础上采取了一系列措施，改变了阿亮。李老师的做法最能体现的德育原则是（）", "opts": ["疏导原则", "在集体中教育的原则", "理论与生活相结合的原则", "严格要求与尊重学生相结合的原则"], "a": 0, "exp": "本题考查的知识点是德育原则。A选项，疏导原则是指在进行德育时要循循善诱、以理服人，从提高学生认识人手，调动学生的主动性，使他们积极向上。李老师跟阿亮谈心，肯定阿亮对电脑技术学习的积极性，借此了解了阿亮的内心世界，这是贯彻疏导原则的体现。故A选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|15", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 15, "q": "晚自习中，李老师发现学生林林在座位上偷偷看课外书，于是一边快步上前收书，一边批评道：“成绩那么差，课内的都还没消化，有什么资格看课外书！”林林与其争辩起来，拉扯中，书被撕碎了。李老师的做法主要违背的教学德育原则是（）", "opts": ["发扬积极因素，克服消极因素原则", "严格要求与尊重学生相结合原则", "理论和实践相结合原则", "疏导原则"], "a": 1, "exp": "题干中，老师对学生只作了严格要求而没有尊重学生。因此违背了严格要求与尊重学生相结合的原则。故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|16", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 16, "q": "“长善救失”体现的德育原则是（", "opts": ["疏导原则", "理论与实践相结合原则", "严格要求与尊重学生相结合原则", "发扬积极因素、克服消极因素原则"], "a": 3, "exp": "发扬积极因素，克服消极因素的原则（长善救失原则）是指在德育工作中，教育者要善于依靠、发扬学生自身的积极因素，调动学生自我教育的积极性，克服消极因素，实现品德发展内部矛盾的转化。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|17", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 17, "q": "小张在放学回家路上将摔倒昏迷的老人送进医院，及时挽救了老人生命。为此，班主任在班上公开表扬小张的行为，号召大家向他学习。这是运用了教育方法中的（）", "opts": ["说理教育法", "榜样示范法", "实际锻炼法", "陶冶教育法"], "a": 1, "exp": "本题考查的知识点是德育方法。B选项，榜样示范法是教育者以他人的高尚思想、模范行为和卓越成就影响学生，促使其形成优良品德的方法。题干中班主任号召大家向做好事的小张学习，是为其他学生树立了榜样。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|18", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 18, "q": "利用校园的花坛、草坪影响学生的品德，这种德育方法是（", "opts": ["品德评价法", "榜样示范法", "情境陶冶法", "说服教育法"], "a": 2, "exp": "本题考查的知识点是德育方法。情境陶冶法又称陶冶教育法，是指教师利用高尚的情感、美好的事物和优美的环境感染和黑陶学生的方法。该方法主要运用以境染情、以境触情、以境陶情的原理对受教育者进行耳潘目染、潜移默化的影响，使受教育者在认识上和情感上逐渐完善。情感陶冶包括人格感化、环境陶冶和艺术陶冶等。题干中利用花坛、草坪影响学生的品德，属于情境陶冶法。因此本题正确答案为C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|19", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 19, "q": "为了提醒幼儿便后冲水，秦老师在每一个马桶盖上都贴上了一张特别漂亮且富有提）示意义的卡通画，效果很好。秦老师的这一做法运用的教育方法是（", "opts": ["榜样示范法", "说服教育法", "情境陶冶法", "品德评价法"], "a": 2, "exp": "/本题考查的知识点是德育方法。C选项，德育的情境陶冶法是指教育者利用高尚的情感、美好的事物和优美的环境感染和熏陶学生的方法。秦老师通过卡通画的方式潜移默化地影响学生是利用了环境感染的方式。故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|20", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 20, "q": "“身教重于言教”体现的德育方法是（", "opts": ["说理教育法", "榜样示范法", "情境陶冶法", "实践锻炼法"], "a": 1, "exp": "本题考查的知识点是德育方法。B选项，榜样示范法是以他人的高尚品德、模范行为和卓越成就来响学生品德的方法。题干中“身教重于言教”表明了教师的道德行为对学生的重要影响，强调了榜样的力量，属于榜样示范法。故B选项符合题意。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|21", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 21, "q": "班主任根据学生的认知发展特点，选出有针对性的人物和事例鼓励学生，不断提高学）生修养，该教师采用的德育方法是（", "opts": ["品德修养法", "实践锻炼法", "榜样示范法", "制度育德法"], "a": 2, "exp": "本题考查的知识点是德育方法。C选项，榜样示范法是用榜样人物的高尚思想、模范行为、优异成就来影响学生的思想、情感和行为的方法。用来示范的榜样主要有家长和教师、同学、英雄人物、革命领袖、历史伟人和文艺形象。题干中，班主任利用有针对性的人物和事例鼓励学生，从而提高学生修养，运用了榜样示范法。因此，C选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|22", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 22, "q": "小学二年级的娜娜帮助同学打扫卫生，老师奖励了她一朵小红花。此后她更乐于助人了。该老师运用的德育方法是（", "opts": ["情感陶冶法", "说服教育法", "榜样示范法", "品德评价法"], "a": 3, "exp": "题干的教师通过奖励娜娜小红花强化她乐于助人的行为，体现了品德评价法，故选D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b103|23", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 23, "q": "我国古代教育提倡“论学取友”“择其善者而从之”。这体现的德育方法是（", "opts": ["说服教育法", "自我修养法", "榜样示范法", "倩境陶冶法"], "a": 2, "exp": "题干中，“论学取友”的意思是：根据在学术上的见解，对朋友进行选择。“择其善者而从之”的意思是：选择别人好的方面向他学习。这体现的是选择好学习的榜样对人品德的发展和形成有着重要的影响，选好榜样是学习的前提。故本题答案选择C选项", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b105|24", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 24, "q": "【2007年311真题5】按照科尔伯格的理论，以人际关系和谐或“好孩子”为定向的道德发展阶段处于（）", "opts": ["前习俗水平", "习俗水平", "后习俗水平", "准习俗水平"], "a": 1, "exp": "A选项“前习俗水平”出现在幼儿园及小学中低年级，包括服从与惩罚的定向阶段和工具性的相对主义定向阶段。C选项“后习俗水平”包括社会契约的定向阶段和普遍道德原则的定向阶段。D选项说法不存在。B选项“习俗水平”出现在小学中高年级及初中，包括人际关系和谐（或“好孩子”）的定向阶段和维护权威或秩序的定向阶段。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b106|25", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 25, "q": "【2010年311真题11】根据体谅模式，下述教例中对情境问题做出了成熟反应的学生是（）教师：如果你同别人说话时，一个你认识的人不停地插嘴并且试图改变话题，你怎么办？学生甲：躲开他，然后继续我们的谈话。学生乙：让他加人我们的谈话，看看他到底是什么意思。学生丙：告诉老师，老师会批评他。学生丁：也许是我们冷落了他，既然他想加人进来，就一起聊好了。学生戊：也许我们的话题使他不安，既然他想改变话题，就别当着他的面说这个话题了。", "opts": ["甲和乙", "乙和丙", "丙和丁", "丁和戊"], "a": 3, "exp": "体谅模式的实质是让学生学会换位思考。题干中“作出了成熟反应的学生”，实质是会换位思考的学生。本题如果不确定乙的说法是否是换位思考的话，可用排除法。甲不考虑认识的人的立场，选择躲开；丙选择告诉老师，让老师批评他。这都不是换位思考，故排除甲和丙，答案为D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b106|26", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 26, "q": "【2011年311真题10】通过对道德两难问题的深人讨论，儿童倾向于拒斤低于自己道德发展阶段的同伴的道德推理，并且能够理解和同化高于自己一个阶段的同伴的道德推理，但难以理解和接受高于自己两个或两个以上阶段的同伴的道德推理。这种现象被科尔伯格等人称为（）", "opts": ["皮格马利翁效应", "俄狄浦斯效应", "布莱特效应", "布朗效应"], "a": 2, "exp": "本题是对识记性知识的考查。A选项皮格马利翁效应即罗森塔尔效应，也称为教师期望效应；B选项俄狄浦斯效应指恋母情结；D选项布朗效应是物理学的知识点，和教育学没有关系，描述的是分子的热运动。题干内容属于布莱特效应。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b106|27", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 27, "q": "【2012年311真题9】体谅模式与其他德育模式的区别在于（", "opts": ["把道德情感的培养放在中心地位", "把道德认知发展放在中心地位", "把道德行为学习放在中心地位", "把道德价值观念的获得放在中心地位"], "a": 0, "exp": "体谅模式把道德情感的培养放在中心地位。道德认知发展模式将道德认知放在中心地位。班杜拉的社会学习模式关注道德行为的获得。价值澄清模式注重道德价值观念的获得。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b106|28", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 28, "q": "学生道德发展，其依据是人的道德发展具有（）", "opts": ["阶段性、顺序性、差异性", "阶段性、差异性、不平衡性", "顺序性、差异性、不平衡性", "阶段性、顺序性、不平衡性"], "a": 0, "exp": "道德两难法和公正团体法是道德认知发展模式所采取的教育方法。儿童在不同的发展阶段有不同的道德发展水平，体现了发展的阶段性；儿童的道德发展具有一定的顺序性，比如从前习俗水平到习俗水平再到后习俗水平，是顺序发展的过程；不同个体的儿童道德发展水平不同，具有一定的差异性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b106|29", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 29, "q": "【2013年311真题9】为避免灌输与说教而大量使用道德问题情境激发学生角色认取(roletaking）和主动思考的德育模式，除道德认知发展模式外，还有（）", "opts": ["体谅模式", "价值澄清模式", "社会学习模式", "集体教育模式"], "a": 0, "exp": "体谅模式注重学生的道德情感，以问题情境激发学生道德情感的发展。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b106|30", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 30, "q": "【2014年311真题9】体谅模式使用诸如“有人在乘车时不停地跟司机说笑话，接着可能发生什么？”之类的人际互动情境问题，组织学生交流经验，续写故事或画连环画，分组合作编写和表演情景剧，其直接目的在于引导学生（）", "opts": ["置身事外，从旁观者的立场客观评价他人的处境和需求", "设身处地，从参与者的立场感受他人的处境和需求", "设身处地，从参与者的立场预估人际行为后果", "置身事外，从旁观者的立场预估人际行为后果"], "a": 3, "exp": "20世纪80年代，英国以麦克菲尔《生命线》教材为蓝本，开发了面向中学生的学校德育课程。在第一部分设置了敏感性、后果和观点三个单元。后果单元由71张情境卡构成，相比敏感性单元的情境卡，这些情境卡包含更复杂的情况，涉及更多的人物和方面，激发学生思考第三者及其他客观因素，即引导学生采取旁观者的立场客观地思考诸多事件的各种“后果”，以增强学生对行为后果的想象、理解和推测的能力。故本题选D选项置身事外，从旁观者的立场预估人际行为后果。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b106|31", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 31, "q": "【2017年311真题3】以下道德教育模式中，将“学会选择”作为核心理念的是（）", "opts": ["价值澄清模式", "认知发展模式", "体谅模式", "社会学习模式"], "a": 1, "exp": "《生命线》是麦克菲尔（又译为麦克费尔）针对体谅模式编写的教材。A选项《学会关心》是内尔·诺丁斯在关心伦理与教育方面的一本重要著作。么办？”。32119363788811.【答案】AA选项价值澄清模式是让学生在不同的价值观念中进行选择；B选项认知发展模式是皮亚杰所强调的儿童道德的发展是经历他律到自律的转化过程，或指科尔会学习模式强调他人、团体的作用。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b106|32", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 32, "q": "【2019年311真题12】谢老师在班会上问学生：有个同学在上课时对老师说了不敬的话，接下来可能会发生什么？学生们自由发言，说出了各种可能的师生互动方案。谢老师把学生分成多个小组，每个小组表演其中一种方案，全班学生边看边评议各组演得像不像。谢老师这一做法属于（（）", "opts": ["认知发展模式", "体谅模式", "价值澄清模式", "社会学习模式"], "a": 1, "exp": "角色扮演对应体谅模式和价值澄清模式，排除A选项和D选项。价值澄清模式是针对多种价值观的选择而提出的；体谅模式是为了与人友好相处。本题是引导学生站在师生角度进行考虑，因此是体谅模式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b106|33", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 33, "q": "【2021年311真题9】小丁不怎么懂得拒绝别人。有一天.小丁和爸爸正高兴地打着羽毛球，小红过来说也要玩。小丁把球拍让给了小红，可是一脸不情愿的样子。回家的路上，爸爸对小丁说：“你如果还想玩，可以对小红说，我再玩一会儿就给你。”从德）育途径上说，爸爸的做法属于（", "opts": ["指导育人", "环境育人", "活动育人", "管理育人"], "a": 0, "exp": "题干中爸爸给小丁提出了解决问题的方案。从德育途径上说，这属于指导育人。二、分析论述题1.【参考答案】（1）讨论法是学生在教师指导下为解决某个问题进行探讨、评析，以辨明是非真伪、", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b109|34", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 34, "q": "历史、地理等课要利用课程中传统文化、历史地理等丰富的思想道德因素，潜移默化地对学生进行世界观、人生观和价值观的引导，这体现的是德育的何种育人途径（）", "opts": ["活动育人", "课程育人", "实践育人", "协同育人"], "a": 3, "exp": "根据题目中的“利用课程中传统文化、历史地理等丰富的思想道德因素，行德育，体现的是课程育人这一德育途径。通，属于指导育人的方式。所以答案为D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-08|b109|35", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-08", "chName": "", "sec": "基础练习", "no": 35, "q": "基于人本主义和行为主义的观点，明确提出反对在道德教育中运用高度理性化的方法，认为这可能会对学生情感与行为的发展产生影响，因此主张道德教育应运用个性模式而非推理的道德教育模式是（", "opts": ["道德认知发展模式", "体谅模式", "价值澄清模式", "社会学习模式"], "a": 1, "exp": "体谅模式基于人本主义和行为主义，强调个性发展，反对简单的道德说教，主张通过体谅、耐心、情感等促进道德发展。而道德认知发展模式强调道德推理的发展。价值澄清模式强调理性的价值分析。社会学习模式强调环境的模仿。综上所述，题目描述的观点反映了体谅模式的理念。·第八章德育KUKU二、材料分析题【参考答案】（1）材料中李老师的德育实践是体谅模式与集体教育模式的融合：①体谅模式：体谅模式将道德情感的培养放在中心地位，强调教育即学会关心。李老师尊重学生个性差异，鼓励内向学生表达，引导好动学生投人实验；包容学生错误，先肯定思考过程再讲解。他以关注学生情感需求、消除学生焦虑为核心，实现“以情育德”，让学生自发规范行为。②集体教育模式：集体教育模式是通过集体、在集体中、为了集体的教育。李老师通过“成长分享会”组织学生自评互评，营造“互帮互改”的集体氛围；班级无需强调纪律却能有序运转，体现“集体影响个体、个体强化集体”的双向促进，为德育目标实现提供支撑。(2）李老师的评价方式紧扣“改进结果评价、强化过程评价、探索增值评价、健全综合评价”要求，推进评价观念与方式改革：①更新评价观念：强化素养导向，既评价学生学业表现，关注解题思路与计算准确性，也评价学生品格与能力，重视团队合作意识；倡导“评价促进学习”的理念，借助评语引导学生反思改进，通过“成长分享会”提升学生自我评价能力。②创新评价方式：强化过程评价，用作业本批注记录学生学习过程，倡导基于证据的评价；关注学生真实发生的进步，积极探索增值评价，认可学生的个体成长；加强对话交流，通过自评互评增强评价双方反思改进意识，倡导协商式评价；结合日常表现，用“努力之星”等荣誉评选推进表现性评价，综合运用多种评价方式。(3）李老师和学生构建了“尊师爱生、相互配合；民主平等、和谐亲密；教学相长、心理相容”的新型师生关系。①尊师爱生、相互配合：学生主动整理桌面、期待上课，以此表达对教师的尊重；李老师关爱学生，针对不同学生特点进行差异化引导，包容学生错误，师生配合默契，无须强制约束就能保持良好秩序。②民主平等、和谐亲密：李老师平等对待所有学生，没有偏爱成绩优异者，也", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-09|b112|1", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-09", "chName": "", "sec": "基础练习", "no": 1, "q": "【2009年311真题13】下列选项中，属于《中华人民共和国教师法》明确规定的教师专业权利的是(", "opts": ["指导学生学习与发展的权利", "对学校进行管理与领导的权利", "选择教材教法开展教学工作的权利", "检查与评价学生品行、学业、身体的权利"], "a": 0, "exp": "教师有教育教学自主权、指导评价权、专业发展权以及其他属于劳动者的合法权利，如休息休假、取得劳动报酬等。其余选项本身表述存在问题。B选项本身不对，教师享有的是参与管理权，不是直接管理学校。C选项中，教师没有选择教材的权利，教材的编写和选择是由国家负责的。现在有校本教材体现了教师选择教材的自主权，但是这没有在法律层面进行规定。D选项中，教师没有评价学生身体的权利。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-09|b112|2", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-09", "chName": "", "sec": "基础练习", "no": 2, "q": "【2010年311真题13】下列选项中，能够体现教师劳动具有专业性的是（1.教师工作是基于专门知识和技能的智力劳动Ⅱ.教师在工作中必须遵循一套独特的职业道德要求Ⅲ.教师劳动的成效具有滞后性IV.教师的工作时间和业余时间没有明显的界线", "opts": ["I、Ⅱ", "Ⅱ、Ⅲ", "Ⅲ、IV", "1、IV"], "a": 0, "exp": "教师劳动的专业性是指专业理想、专业知识、专业能力和专业自我。Ⅲ和1931637888IV反而是教师劳动专业化程度不够的体现。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}]);
